#!/usr/bin/env python3
"""读取 CSV 文件并统计每一列的非空值数量。"""

import argparse
import csv
import sys


def count_non_null(path):
    counts = {}
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return counts
        for col in header:
            counts[col] = 0
        for row in reader:
            for i, value in enumerate(row):
                if i in range(len(header)) and value.strip():
                    counts[header[i]] += 1
    return counts


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    args = parser.parse_args()

    try:
        counts = count_non_null(args.csv_file)
    except FileNotFoundError:
        print(f"错误：文件不存在: {args.csv_file}", file=sys.stderr)
        sys.exit(1)

    if not counts:
        print("CSV 文件为空")
        sys.exit(0)

    width = max(len(col) for col in counts)
    for col, count in counts.items():
        print(f"{col:<{width}}  {count}")


if __name__ == "__main__":
    main()
